chart.options:
chart: {
          type: 'bar',
          height: 380,
          stacked: true,
        },
        plotOptions: {
          bar: {
            horizontal: false,
            borderRadius: 10,
            borderRadiusApplication: 'end',
          },
        },
        colors: ['#008FFB', '#4FC3F7', '#00E396', '#66DA26'],
        dataLabels: {
          enabled: false,
        },
        stroke: {
          width: 1,
          colors: ['#fff'],
        },
        title: {
          text: 'grouped column, mixed: every group caps its own stack',
          style: { fontSize: '13px', fontWeight: 500 },
        },
        xaxis: {
          categories: ['Q1', 'Q2', 'Q3', 'Q4'],
        },
        legend: {
          position: 'top',
        }
